{
	"name": "daz-pilot",
	"version": "0.0.1",
	"description": "Eine App für den Berufsschulunterricht zur Förderung und Nachbereitung von Fachvokabular für Schüler:innen mit Sprachbarrieren.",
	"repository": {
		"type": "git",
		"url": "git@gitlab.opencode.de:sh/digitalhub-sh/landesprogramm-offene-innovationen/daz-pilot.git"
	},
	"license": "EUPL-1.2",
	"author": "",
	"directories": {
		"doc": "docs"
	},
	"scripts": {
		"format": "npm --prefix ./app run format && npm --prefix ./backend run format && npm --prefix ./dashboard run format",
		"postinstall": "npm --prefix ./backend install && npm --prefix ./backend run build --workspace=@daz-pilot/daz-pilot-backend-api-types && npm --prefix ./app install && npm --prefix ./dashboard install",
		"install:proof_of_concept": "npm --prefix ./proof_of_concept/app install && npm --prefix ./proof_of_concept/backend install",
		"docker:up": "docker compose up -d --build",
		"docker:local": "docker compose -f docker-compose.yml -f docker-compose.local.yml up --build",
		"docker:dev": "docker compose -f docker-compose.yml -f docker-compose.local.yml -f docker-compose.dev.yml up --build",
		"docker:down": "docker compose down",
		"prepare": "husky"
	},
	"devDependencies": {
		"husky": "^9.1.7"
	}
}
